/**
 * ʿAqīda malikite-ashʿarite : partie du matn d’Ibn ʿĀshir seulement.
 * Arabe vocalisé : Guiding Helper Foundation, 2005, copié sans modification.
 * Les maʿnawiyya sont un bloc à part (structure d’Umm al-Barāhīn), sans vers d’al-Sanūsī.
 */
import { buildLocales, FLAG_SCHOLAR, FLAG_TRANSLATION, type ContentLocale, type LocaleMap } from './religious-locale';

export const AQIDA_EDITION = "Guiding Helper Foundation, al-Murshid al-Muʿīn, révision arabe du 20 février 2004 (29 dhū al-ḥijja 1424). Reproduction non altérée. © 2005 : autorisation générale et non restreinte de dupliquer ce texte sans le modifier. Le poème d’Ibn ʿĀshir (m. 1040/1631) est dans le domaine public ; cette vocalisation est celle de cette édition, pas l’imprimé thaʿālibī de 1343 h.";
export const AQIDA_ENGLISH_SOURCE = "Guiding Helper Foundation, al-Murshid al-Muʿīn, English revision 18 February 2005 (9 Muḥarram 1426). Unaltered duplication. © 2005, general and unrestricted permission for the unaltered duplication of this text.";
export const AQIDA_SCHOLAR_FLAG = FLAG_SCHOLAR;

const FR = "Traduction littérale Zikru sur le matn vocalisé de l’édition citée. Les termes techniques restent en arabe translittéré.";
const DE = "Wörtliche Übersetzung Zikru nach dem vokalisierten matn der genannten Ausgabe. Fachwörter bleiben in Umschrift.";
const ARNOTE = "شرح موجز على المتن، وليس المتن. صيغته من إعداد التطبيق وعلى عالم أن يراجعها.";

function verseMap(ar: string, en: string, fr: string, de: string): LocaleMap {
  return buildLocales({
    ar: { text: ar, source: AQIDA_EDITION, kind: 'matn', flag: FLAG_SCHOLAR },
    en: { text: en, source: AQIDA_ENGLISH_SOURCE, kind: 'published', flag: FLAG_TRANSLATION },
    fr: { text: fr, source: FR, kind: 'literal', flag: FLAG_TRANSLATION },
    de: { text: de, source: DE, kind: 'literal', flag: FLAG_TRANSLATION },
  });
}

function noteMap(fr: string, en: string, de: string, ar: string, extra?: Record<string, string>): LocaleMap {
  const base: Parameters<typeof buildLocales>[0] = {
    fr: { text: fr, source: FR, kind: 'literal', flag: FLAG_TRANSLATION },
    en: { text: en, source: 'Zikru literal commentary, beside the cited edition. Not the matn.', kind: 'literal', flag: FLAG_TRANSLATION },
    de: { text: de, source: DE, kind: 'literal', flag: FLAG_TRANSLATION },
    ar: { text: ar, source: ARNOTE, kind: 'literal', flag: FLAG_SCHOLAR },
  };
  for (const [k, text] of Object.entries(extra ?? {})) {
    base[k as ContentLocale] = { text, source: FR, kind: 'literal', flag: FLAG_TRANSLATION };
  }
  return buildLocales(base);
}

export type AqidaVerse = { n: number; arabic: string; translation: LocaleMap; section: string };
export type AqidaAttribute = {
  id: string;
  group: 'nafsiyya' | 'salbiyya' | 'maani' | 'manawiyya';
  block: 'murshid' | 'sanusi';
  arabic: string;
  transliteration: string;
  verse: number | null;
  sourceRef: string;
  scholarFlag: typeof FLAG_SCHOLAR;
  verified: false;
  opposite: { id: string; arabic: string; transliteration: string; verse: number | null; sourceRef: string; scholarFlag: typeof FLAG_SCHOLAR; verified: false };
  gloss: LocaleMap;
};

export const AQIDA_VERSES: readonly AqidaVerse[] = [
  { n: 6, arabic: "وَحُكْمُنَا الْعَقْلِيُّ قَضِيَّةٌ بِلَا\nوَقْفٍ عَلَى عَادَةٍ أَوْ وَضْعِ جَلَا", section: "ahkam", translation: verseMap("وَحُكْمُنَا الْعَقْلِيُّ قَضِيَّةٌ بِلَا\nوَقْفٍ عَلَى عَادَةٍ أَوْ وَضْعِ جَلَا", "Our rational proposition is a statement (subject-predicate pair) (for which one does) not | (need to) stop (and verify its truth) using empirical evidence, or a divinely-revealed text.", "Notre jugement rationnel (ḥukm ʿaqlī) est une proposition (qaḍiyya), sans s’arrêter à une habitude (ʿāda) ni à une institution posée (waḍʿ).", "Unser rationales Urteil (ḥukm ʿaqlī) ist ein Satz (qaḍiyya), ohne bei einer Gewohnheit (ʿāda) oder einer gesetzten Konvention (waḍʿ) stehen zu bleiben.") },
  { n: 7, arabic: "أَقْسَامُ مُقْتَضَاهُ بِالْحَصْرِ تُمَازُ\nوَهِيَ الْوُجُوبُ الِاسْتِحَالَةُ الْجَوَازُ", section: "ahkam", translation: verseMap("أَقْسَامُ مُقْتَضَاهُ بِالْحَصْرِ تُمَازُ\nوَهِيَ الْوُجُوبُ الِاسْتِحَالَةُ الْجَوَازُ", "The types of its instances in encompassment are distinguished | (as three) and they are the necessary, the impossible, and the possible.", "Les divisions de ce qu’il implique se distinguent par exhaustion : al-wujūb (le nécessaire), al-istiḥāla (l’impossible), al-jawāz (le possible).", "Die Arten dessen, was er fordert, scheiden sich erschöpfend: al-wujūb (notwendig), al-istiḥāla (unmöglich), al-jawāz (möglich).") },
  { n: 8, arabic: "فَوَاجِبٌ لَا يَقْبَلُ النَّفْيَ بِحَالِ\nوَمَا أَبَى الثُّبُوتَ عَقْلًا الْمُحَالُ", section: "ahkam", translation: verseMap("فَوَاجِبٌ لَا يَقْبَلُ النَّفْيَ بِحَالِ\nوَمَا أَبَى الثُّبُوتَ عَقْلًا الْمُحَالُ", "The necessary is what cannot accept negation in any condition. | What refuses rational affirmation is the impossible.", "Est wājib ce qui n’accepte la négation en aucun cas. Ce qui refuse l’affirmation pour la raison (ʿaqlan) est al-muḥāl.", "Wājib ist, was die Verneinung in keinem Fall annimmt. Was die Bejahung für die Vernunft (ʿaqlan) verweigert, ist al-muḥāl.") },
  { n: 9, arabic: "وَجَائِزًا مَا قَابَلَ الْأَمْرَيْنِ سِمْ\nلِلضَّرُورِي وَالنَّظَرِي كُلٌّ قُسِمْ", section: "ahkam", translation: verseMap("وَجَائِزًا مَا قَابَلَ الْأَمْرَيْنِ سِمْ\nلِلضَّرُورِي وَالنَّظَرِي كُلٌّ قُسِمْ", "And mark as possible that which can accept both these affairs (i.e. negation and affirmation). | Each of these types is divided into both the immediately known and reflectively known (classes).", "Nomme jāʾiz ce qui accepte les deux affaires. Chacun des trois se partage en ḍarūrī (connu sans examen) et naẓarī (connu par examen).", "Nenne jāʾiz, was beide Seiten annimmt. Jede der drei Arten teilt sich in ḍarūrī (ohne Prüfung bekannt) und naẓarī (durch Prüfung bekannt).") },
  { n: 10, arabic: "أَوَّلُ وَاجِبٍ عَلَى مَنْ كُلِّفَا\nمُمَكَّنًا مِنْ نَظَرٍ أَنْ يَعْرِفَا", section: "ahkam", translation: verseMap("أَوَّلُ وَاجِبٍ عَلَى مَنْ كُلِّفَا\nمُمَكَّنًا مِنْ نَظَرٍ أَنْ يَعْرِفَا", "The first obligation on him who is given responsibility | if he has the ability to search (and reflect) is to know", "La première obligation, pour qui est chargé (mukallaf), s’il peut faire le naẓar, est de connaître.", "Die erste Pflicht für den, der mukallaf ist, wenn er zum naẓar imstande ist: zu erkennen.") },
  { n: 11, arabic: "اللَّهَ وَالرُّسْلَ بِالصِّفَاتِ\nمِمَّا عَلَيْهَا نَصَبَ الْآيَاتِ", section: "ahkam", translation: verseMap("اللَّهَ وَالرُّسْلَ بِالصِّفَاتِ\nمِمَّا عَلَيْهَا نَصَبَ الْآيَاتِ", "Allah and the Messengers with the attributes | for which He has erected signs.", "Allah et les messagers, avec les attributs pour lesquels Il a dressé des signes (āyāt).", "Allah und die Gesandten, mit den Attributen, für die Er Zeichen (āyāt) aufgerichtet hat.") },
  { n: 12, arabic: "وَكُلُّ تَكْلِيفٍ بِشَرْطِ الْعَقْلِ\nمَعَ الْبُلُوغِ بِدَمٍ أَوْ حَمْلِ", section: "ahkam", translation: verseMap("وَكُلُّ تَكْلِيفٍ بِشَرْطِ الْعَقْلِ\nمَعَ الْبُلُوغِ بِدَمٍ أَوْ حَمْلِ", "And every placement of responsibility has the precondition of sanity | along with puberty (reached) by (the appearance of) menstrual blood, pregnancy,", "Tout taklīf a pour condition la raison, avec la bulūgh par le sang ou la grossesse,", "Jedes taklīf hat die Vernunft zur Bedingung, samt der bulūgh durch Blut oder Schwangerschaft,") },
  { n: 13, arabic: "أَوْ بِمَنِيٍّ أَوْ بِإِنْبَاتِ الشَّعَرْ\nأَوْ بِثَمَانِ عَشْرَةٍ حَوْلًا ظَهَرْ", section: "ahkam", translation: verseMap("أَوْ بِمَنِيٍّ أَوْ بِإِنْبَاتِ الشَّعَرْ\nأَوْ بِثَمَانِ عَشْرَةٍ حَوْلًا ظَهَرْ", "Reproductive fluid, or thick pubic hair. | Or (if none of the previous signs of puberty are seen, then responsibility is reached) by the completion of eighteen years (along with sanity).", "ou par le maniyy, ou par la pousse du poil, ou par dix-huit années apparues.", "oder durch maniyy, oder durch sprießendes Haar, oder dadurch, dass achtzehn Jahre erschienen sind.") },
  { n: 14, arabic: "يَجِبُ لِلَّهِ الْوُجُودُ وَالْقِدَمْ\nكَذَا الْبَقَاءُ وَالْغِنَى الْمُطْلَقُ عَمّ", section: "sifat", translation: verseMap("يَجِبُ لِلَّهِ الْوُجُودُ وَالْقِدَمْ\nكَذَا الْبَقَاءُ وَالْغِنَى الْمُطْلَقُ عَمّ", "(The following attributes) are necessary for Allah: (1) existence, (2) beginninglessness, | (3) likewise permanence in continued existence, (4) absolute and universal independence,", "Sont wājib pour Allah : al-wujūd et al-qidam ; de même al-baqāʾ, et al-ghinā al-muṭlaq, qui est général.", "Für Allah wājib: al-wujūd und al-qidam; ebenso al-baqāʾ und al-ghinā al-muṭlaq, umfassend.") },
  { n: 15, arabic: "وَخُلْفُهُ لِخَلْقِهِ بِلَا مِثَالِ\nوَوَحْدَةُ الذَّاتِ وَوَصْفِ وَالْفِعَالِ", section: "sifat", translation: verseMap("وَخُلْفُهُ لِخَلْقِهِ بِلَا مِثَالِ\nوَوَحْدَةُ الذَّاتِ وَوَصْفِ وَالْفِعَالِ", "(5) Being different from His creation without a similitude, | (6) oneness in His Entity, attribute(s), and actions,", "Sa différence d’avec Sa création, sans semblable ; et l’unité de l’essence, de l’attribut et des actes.", "Sein Anderssein gegenüber Seiner Schöpfung, ohne Beispiel; und die Einheit der Essenz, des Attributs und der Handlungen.") },
  { n: 16, arabic: "وَقُدْرَةٌ إِرَادَةٌ عِلْمٌ حَيَاةْ\nسَمْعٌ كَلَامٌ بَصَرٌ ذِي وَاجِبَاتْ", section: "sifat", translation: verseMap("وَقُدْرَةٌ إِرَادَةٌ عِلْمٌ حَيَاةْ\nسَمْعٌ كَلَامٌ بَصَرٌ ذِي وَاجِبَاتْ", "(7) Power, (8) volition, (9) knowledge, (10) life, | (11) hearing, (12) speech, and (13) sight. These are the necessary (attributes of Allah).", "Et qudra, irāda, ʿilm, ḥayāt, samʿ, kalām, baṣar : ce sont des wājibāt.", "Und qudra, irāda, ʿilm, ḥayāt, samʿ, kalām, baṣar: das sind wājibāt.") },
  { n: 17, arabic: "وَيَسْتَحِيلُ ضِدُّ هَذِهِ الصِّفَاتْ\nالْعَدَمُ الْحُدُوثُ ذَا لِلْحَادِثَاتْ", section: "addad", translation: verseMap("وَيَسْتَحِيلُ ضِدُّ هَذِهِ الصِّفَاتْ\nالْعَدَمُ الْحُدُوثُ ذَا لِلْحَادِثَاتْ", "And the opposite of these attributes are impossible (for Allah): | (1) non-existence, (2) having a beginning - these are only for created things,", "L’opposé de ces attributs est mustaḥīl : al-ʿadam, al-ḥudūth — cela appartient aux choses créées.", "Das Gegenteil dieser Attribute ist mustaḥīl: al-ʿadam, al-ḥudūth — das gehört zu den geschaffenen Dingen.") },
  { n: 18, arabic: "كَذَا الْفَنَا وَالِافْتِقَارُ عُدَّهْ\nوَأَنْ يُمَاثِلَ وَنَفْيُ الْوَحْدَةْ", section: "addad", translation: verseMap("كَذَا الْفَنَا وَالِافْتِقَارُ عُدَّهْ\nوَأَنْ يُمَاثِلَ وَنَفْيُ الْوَحْدَةْ", "(3) Likewise fading into non-existence and (4) being in need (of others) are also counted, | (5) that He have a similar, (6) the negation of His oneness,", "De même al-fanāʾ et al-iftiqār : compte-les ; et qu’Il ait un semblable, et la négation de l’unité.", "Ebenso al-fanāʾ und al-iftiqār: zähle sie; und dass Er ein Gleiches habe, und die Verneinung der Einheit.") },
  { n: 19, arabic: "عَجْزٌ كَرَاهَةٌ وَجَهْلٌ وَمَمَاتْ\nوَصَمَمٌ وَبَكَمٌ عَمًى صُمَاتْ", section: "addad", translation: verseMap("عَجْزٌ كَرَاهَةٌ وَجَهْلٌ وَمَمَاتْ\nوَصَمَمٌ وَبَكَمٌ عَمًى صُمَاتْ", "(7) Inability (to perform contingent actions), (8) being forced (to act), (9) ignorance, (10) death, | (11) deafness, (12) dumbness, (13) blindness and silence.", "ʿAjz, karāha, jahl et mamāt ; et ṣamam, bakam, ʿamā, ṣumāt.", "ʿAjz, karāha, jahl und mamāt; und ṣamam, bakam, ʿamā, ṣumāt.") },
  { n: 20, arabic: "يَجُوزُ فِي حَقِّهِ فِعْلُ الْمُمْكِنَاتْ\nبِأَسْرِهَا وَتَرْكُهَا فِي الْعَدَمَاتْ", section: "jaiz", translation: verseMap("يَجُوزُ فِي حَقِّهِ فِعْلُ الْمُمْكِنَاتْ\nبِأَسْرِهَا وَتَرْكُهَا فِي الْعَدَمَاتْ", "It is possible (for Allah) in His right to perform contingent actions | - all of them - and to leave them (unperformed) in non-existence.", "Il est jāʾiz, de Son droit, de faire les possibles, tous, et de les laisser dans les néants.", "Jāʾiz ist in Seinem Recht, die möglichen Dinge zu tun, sie alle, und sie im Nichtsein zu lassen.") },
  { n: 21, arabic: "وَجُودُهُ لَهُ دَلِيلٌ قَاطِعْ\nحَاجَةُ كُلِّ مُحْدَثٍ لِلصَّانِعْ", section: "dalil", translation: verseMap("وَجُودُهُ لَهُ دَلِيلٌ قَاطِعْ\nحَاجَةُ كُلِّ مُحْدَثٍ لِلصَّانِعْ", "His existence has a conclusive proof: | The need of everything that is created in time for a Maker.", "Son existence a une preuve décisive : le besoin de tout muḥdath envers un artisan (ṣāniʿ).", "Seine Existenz hat einen entscheidenden Beweis: das Angewiesensein jedes muḥdath auf einen Verfertiger (ṣāniʿ).") },
  { n: 22, arabic: "لَوْ حَدَثَتْ بِنَفْسِهَا الْأَكْوَانُ\nلَاجْتَمَعَ التَّسَاوِي وَالرُّجْحَانُ", section: "dalil", translation: verseMap("لَوْ حَدَثَتْ بِنَفْسِهَا الْأَكْوَانُ\nلَاجْتَمَعَ التَّسَاوِي وَالرُّجْحَانُ", "If the universe began by itself | equality and preponderance would meet (at the same time (i.e. the metaphor here alludes to the two-sided ancient scale falling to one side (signifying existence) and also be in equality (signifying non existence) in the same instance. The idea here is that someone must place weight on the two sided scale in order for it to show preponderance. In other words, someone must choose the state of existence for a particular physical phenomenon at a particular time since this physical phenomenon could not choose its own existence since it was not present before it was created.)).", "Si les êtres (al-akwān) étaient venus à l’être par eux-mêmes, l’égalité (al-tasāwī) et la prépondérance (al-rujḥān) se seraient réunies.", "Wären die Dinge (al-akwān) von selbst entstanden, so träfen Gleichheit (al-tasāwī) und Überwiegen (al-rujḥān) zusammen.") },
  { n: 23, arabic: "وَذَا مُحَالٌ وَحُدُوثُ الْعَالَمِ\nمِنْ حَدَثِ الْأَعْرَاضِ مَعَ تَلَازُمِ", section: "dalil", translation: verseMap("وَذَا مُحَالٌ وَحُدُوثُ الْعَالَمِ\nمِنْ حَدَثِ الْأَعْرَاضِ مَعَ تَلَازُمِ", "But, that is impossible. And the beginning of the universe | is derived from (looking) at the changes of the attributes (which describe the parts of the universe) and (knowing that attributes are) intrinsically tied (to essences).", "Et cela est muḥāl. Le commencement du monde vient du changement des accidents, avec leur lien à l’essence.", "Und das ist muḥāl. Der Anfang der Welt folgt aus dem Wechsel der Akzidenzien, samt ihrem Band zur Essenz.") },
  { n: 24, arabic: "لَوْ لَمْ يَكُ الْقِدَمُ وَصْفَهُ لَزِمْ\nحُدُوثُهُ دَوْرٌ تَسَلْسُلٌ حُتِمْ", section: "dalil", translation: verseMap("لَوْ لَمْ يَكُ الْقِدَمُ وَصْفَهُ لَزِمْ\nحُدُوثُهُ دَوْرٌ تَسَلْسُلٌ حُتِمْ", "If beginninglessness were not His necessary attribute, | His having a beginning would obligate an infinite loop or regress.", "Si al-qidam n’était pas Son attribut, Son commencement s’ensuivrait : cercle (dawr) ou régression (tasalsul), nécessairement.", "Wäre al-qidam nicht Sein Attribut, folgte Sein Anfang: Zirkel (dawr) oder Reihe (tasalsul), notwendig.") },
  { n: 25, arabic: "لَوْ أَمْكَنَ الْفَنَاءُ لَانْتَفَى الْقِدَمْ\nلَوْ مَاثَلَ الْخَلْقَ حُدُوثُهُ انْحَتَمْ", section: "dalil", translation: verseMap("لَوْ أَمْكَنَ الْفَنَاءُ لَانْتَفَى الْقِدَمْ\nلَوْ مَاثَلَ الْخَلْقَ حُدُوثُهُ انْحَتَمْ", "If He were able to pass into non-existence, His attribute of beginninglessness would be negated. | If He were similar to creation, His having a beginning would definitely be true.", "Si al-fanāʾ était possible, al-qidam serait nié. S’Il ressemblait à la création, Son commencement serait nécessaire.", "Wäre al-fanāʾ möglich, fiele al-qidam weg. Gliche Er der Schöpfung, wäre Sein Anfang notwendig.") },
  { n: 26, arabic: "لَوْ لَمْ يَجِبْ وَصْفُ الْغِنَى لَهُ افْتَقَرْ\nلَوْ لَمْ يَكُنْ بِوَاحِدٍ لَمَا قَدَرْ", section: "dalil", translation: verseMap("لَوْ لَمْ يَجِبْ وَصْفُ الْغِنَى لَهُ افْتَقَرْ\nلَوْ لَمْ يَكُنْ بِوَاحِدٍ لَمَا قَدَرْ", "If independence were not His necessary attribute, He would be in need (of a Maker Himself). | If He were not one, then He would not be able (to perform actions).", "Si l’attribut du ghinā n’était pas wājib pour Lui, Il serait dans le besoin. S’Il n’était pas un, Il ne pourrait pas.", "Wäre das Attribut des ghinā für Ihn nicht wājib, wäre Er bedürftig. Wäre Er nicht einer, könnte Er nicht.") },
  { n: 27, arabic: "لَوْ لَمْ يَكُنْ حَيًّا مُرِيدًا عَالِمَا\nوَقَادِرًا لَمَا رَأَيْتَ عَالَمَا", section: "dalil", translation: verseMap("لَوْ لَمْ يَكُنْ حَيًّا مُرِيدًا عَالِمَا\nوَقَادِرًا لَمَا رَأَيْتَ عَالَمَا", "If He were not Living, Willing, Knowing, | and Powerful, you would not see a world (full of wondrous creation).", "S’Il n’était pas vivant, voulant, sachant et puissant, tu ne verrais pas un monde.", "Wäre Er nicht lebend, wollend, wissend und mächtig, sähest du keine Welt.") },
  { n: 28, arabic: "وَالثَّانِي فِي السِّتِّ الْقَضَايَا بَاطِلُ\nقَطْعًا مُقَدَّمٌ إِذًا مُمَاثِلُ", section: "dalil", translation: verseMap("وَالثَّانِي فِي السِّتِّ الْقَضَايَا بَاطِلُ\nقَطْعًا مُقَدَّمٌ إِذًا مُمَاثِلُ", "The second part of the six if-then clauses above are false. | So, (it follows that) the first part is also similar (in being false).", "Le second membre des six propositions est faux, de façon décisive. Le premier membre lui est donc semblable.", "Das zweite Glied der sechs Sätze ist entschieden falsch. Das erste Glied ist ihm also gleich.") },
  { n: 29, arabic: "وَالسَّمْعُ وَالْبَصَرُ وَالْكَلَامُ\nبِالنَّقْلِ مَعْ كَمَالِهِ تُرَامُ", section: "dalil", translation: verseMap("وَالسَّمْعُ وَالْبَصَرُ وَالْكَلَامُ\nبِالنَّقْلِ مَعْ كَمَالِهِ تُرَامُ", "Hearing, Sight, and Speech | are taken from the transmission (in the primary texts) and also properly fit in with His perfection.", "L’ouïe, la vue et la parole sont visées par la transmission (naql), avec Sa perfection.", "Hören, Sehen und Sprechen werden durch die Überlieferung (naql) gefordert, samt Seiner Vollkommenheit.") },
  { n: 30, arabic: "لَوِ اسْتَحَالَ مُمْكِنٌ أَوْ وَجَبَا\nقَلْبَ الْحَقَائِقِ لُزُومًا أَوْجَبَا", section: "dalil", translation: verseMap("لَوِ اسْتَحَالَ مُمْكِنٌ أَوْ وَجَبَا\nقَلْبَ الْحَقَائِقِ لُزُومًا أَوْجَبَا", "If a contingently possible affair were impossible or necessary, | it would obligate a change in the realities (of the physical world).", "Si un possible était impossible ou nécessaire, cela imposerait le renversement des réalités.", "Wäre ein Mögliches unmöglich oder notwendig, erzwänge das die Umkehr der Wirklichkeiten.") },
  { n: 31, arabic: "يَجِبُ لِلرُّسْلِ الْكِرَامِ الصِّدْقُ\nأَمَانَةٌ تَبْلِيغُهُمْ يَحِقُّ", section: "rusul", translation: verseMap("يَجِبُ لِلرُّسْلِ الْكِرَامِ الصِّدْقُ\nأَمَانَةٌ تَبْلِيغُهُمْ يَحِقُّ", "(The following attributes) are necessary for the noble messengers: (1) truthfulness, | (2) trustworthiness in obedience, and (3) conveyance of the message in truth,", "Sont wājib pour les nobles messagers : al-ṣidq, l’amāna, et leur tablīgh.", "Für die edlen Gesandten wājib: al-ṣidq, die amāna und ihr tablīgh.") },
  { n: 32, arabic: "مُحَالٌ الْكَذِبُ وَالْمَنْهِيُّ\nكَعَدَمِ التَّبْلِيغِ يَا ذَكِيُّ", section: "rusul", translation: verseMap("مُحَالٌ الْكَذِبُ وَالْمَنْهِيُّ\nكَعَدَمِ التَّبْلِيغِ يَا ذَكِيُّ", "(The following attributes) are impossible (for the messengers): (2) lying/dishonesty, (2) acting in disobedience, | and (3) not conveying. (So, understand this) O intelligent one (and intelligence is also counted by many as a necessary attribute of the messengers).", "Sont muḥāl le mensonge et l’acte interdit, comme l’absence de tablīgh. Le vers dit : yā dhakiyy. Il ne nomme pas faṭāna comme un quatrième mot.", "Muḥāl sind die Lüge und die verbotene Tat, wie das Ausbleiben des tablīgh. Der Vers sagt: yā dhakiyy. Er nennt faṭāna nicht als viertes Wort.") },
  { n: 33, arabic: "يَجُوزُ فِي حَقِّهِمْ كُلُّ عَرَضْ\nلَيْسَ مُؤَدِّيًا لِنَقْصٍ كَالْمَرَضْ", section: "rusul", translation: verseMap("يَجُوزُ فِي حَقِّهِمْ كُلُّ عَرَضْ\nلَيْسَ مُؤَدِّيًا لِنَقْصٍ كَالْمَرَضْ", "It is possible in their right to be described by every (normal human) attribute | which does not diminish (from their role of conveyance), such as mild illness.", "Est jāʾiz, de leur droit, tout accident qui n’entraîne pas une diminution, comme la maladie.", "Jāʾiz ist in ihrem Recht jedes Akzidens, das keine Minderung bringt, wie die Krankheit.") },
  { n: 34, arabic: "لَوْ لَمْ يَكُونُوا صَادِقِينَ لَلَزِمْ\nأَنْ يَكْذِبَ الْإِلَهُ فِي تَصْدِيقِهِمْ", section: "rusul", translation: verseMap("لَوْ لَمْ يَكُونُوا صَادِقِينَ لَلَزِمْ\nأَنْ يَكْذِبَ الْإِلَهُ فِي تَصْدِيقِهِمْ", "If they were not truthful, it would be necessary | that the God had lied in verifying them -", "S’ils n’étaient pas véridiques, il s’ensuivrait qu’Allah mente en les confirmant.", "Wären sie nicht wahrhaftig, folgte, dass Allah sie bestätigend löge.") },
  { n: 35, arabic: "إِذْ مُعْجِزَاتُهُمْ كَقَوْلِهِ وَبَرّ\nصَدَقَ هَذَا الْعَبْدُ فِي كُلِّ خَبَرْ", section: "rusul", translation: verseMap("إِذْ مُعْجِزَاتُهُمْ كَقَوْلِهِ وَبَرّ\nصَدَقَ هَذَا الْعَبْدُ فِي كُلِّ خَبَرْ", "Since their miracles are like His statement which is true, | \"This slave (of Mine) has spoken the truth in all his reports.\"", "Car leurs miracles sont comme Sa parole, et elle est établie : « Cet esclave a dit vrai dans toute information. » Ce sont les mots du vers, pas un hadith ajouté.", "Denn ihre Wunder sind wie Sein Wort, und es steht fest: « Dieser Diener hat in jeder Nachricht die Wahrheit gesagt. » Das sind die Wörter des Verses, kein hinzugefügter Hadith.") },
  { n: 36, arabic: "لَوِ انْتَفَى التَّبْلِيغُ أَوْ خَانُوا حُتِمْ\nأَنْ يُقْلَبَ الْمَنْهِيُّ طَاعَةً لَهُمْ", section: "rusul", translation: verseMap("لَوِ انْتَفَى التَّبْلِيغُ أَوْ خَانُوا حُتِمْ\nأَنْ يُقْلَبَ الْمَنْهِيُّ طَاعَةً لَهُمْ", "If conveyance were negated or they betrayed the trust (by disobeying), it would obligate | that the prohibited act be turned into an act of obedience for them (since we are asked to imitate them and all acts are arbitrary).", "Si le tablīgh manquait ou s’ils trahissaient, il s’ensuivrait que l’interdit devienne pour eux obéissance.", "Fiele der tablīgh weg oder brächen sie die Treue, folgte, dass das Verbotene für sie zu Gehorsam würde.") },
  { n: 37, arabic: "جَوَازُ الْأَعْرَاضِ عَلَيْهِمْ حُجَّتُهْ\nوُقُوعُهَا بِهِمْ تَسَلٍّ حِكْمَتُهْ", section: "rusul", translation: verseMap("جَوَازُ الْأَعْرَاضِ عَلَيْهِمْ حُجَّتُهْ\nوُقُوعُهَا بِهِمْ تَسَلٍّ حِكْمَتُهْ", "The permissibility of normal human afflictions befalling them is the argument against those (who deny the prophets based on their meek humanness). | And these normal states actually befalling them (is the proof that they are possible for them) and the wisdom behind this is to console the messengers (and inform others of the low value of this world as compared to the next world).", "La possibilité des accidents sur eux est l’argument. Leur survenue est une consolation (tasallin) : telle est la sagesse dite par le vers.", "Die Möglichkeit der Akzidenzien an ihnen ist der Beweisgrund. Ihr Eintreten ist ein Trost (tasallin): das ist die Weisheit, die der Vers nennt.") },
  { n: 38, arabic: "وَقَوْلُ لَا إِلَهَ إِلَّا اللَّهُ\nمُحَمَّدٌ أَرْسَلَهُ الْإِلَهُ", section: "shahada", translation: verseMap("وَقَوْلُ لَا إِلَهَ إِلَّا اللَّهُ\nمُحَمَّدٌ أَرْسَلَهُ الْإِلَهُ", "And the statement: There is no god but Allah | (and) Muhammad was sent by the One God -", "Et la parole : lā ilāha illā Allāh ; Muḥammad, Allah l’a envoyé.", "Und das Wort: lā ilāha illā Allāh; Muḥammad, Allah hat ihn gesandt.") },
  { n: 39, arabic: "يَجْمَعُ كُلَّ هَذِهِ الْمَعَانِي\nكَانَتْ لِذَا عَلَامَةَ الْإِيمَانِ", section: "shahada", translation: verseMap("يَجْمَعُ كُلَّ هَذِهِ الْمَعَانِي\nكَانَتْ لِذَا عَلَامَةَ الْإِيمَانِ", "Gathers all of these meanings (mentioned above). | For this reason, it is considered the sign of faith.", "Elle rassemble tous ces sens. Elle est pour cela le signe de la foi.", "Es versammelt alle diese Bedeutungen. Darum ist es das Zeichen des Glaubens.") },
  { n: 40, arabic: "وَهِيَ أَفْضَلُ وُجُوهِ الذِّكْرِ\nفَاشْغَلْ بِهَا الْعُمْرَ تَفُزْ بِالذُّخْرِ", section: "shahada", translation: verseMap("وَهِيَ أَفْضَلُ وُجُوهِ الذِّكْرِ\nفَاشْغَلْ بِهَا الْعُمْرَ تَفُزْ بِالذُّخْرِ", "And this statement is the best of all types of verbal remembrances. | So, busy yourself with it throughout your life and you will be victorious in gaining the treasure.", "Et elle est la meilleure des formes du dhikr. Occupe-t’en ta vie : tu obtiendras le trésor (dhukhr).", "Und es ist die beste Art des dhikr. Beschäftige damit dein Leben: du erlangst den Schatz (dhukhr).") },
];

const MURSHID_REF = (n: number) => "al-Murshid al-Muʿīn (Ibn ʿĀshir), Guiding Helper Foundation 2005, vers " + n;
const SANUSI_REF = "Hors hémistiche d’Ibn ʿĀshir. Structure d’Umm al-Barāhīn (al-Sanūsī), bloc distinct. Aucun vers d’al-Sanūsī n’est cité. Concomitant du vers 16 (maʿnā) et du vers 19 (opposé).";

