export function aqidaVerse(n: number): AqidaVerse {
  const v = AQIDA_VERSES.find((x) => x.n === n);
  if (!v) throw new Error('vers absent : ' + n);
  return v;
}

export function sectionAttributes(id: string): readonly AqidaAttribute[] {
  if (id === 'sifat') return AQIDA_ATTRIBUTES.filter((a) => a.block === 'murshid');
  if (id === 'addad') return AQIDA_ATTRIBUTES.filter((a) => a.block === 'murshid');
  if (id === 'manawiyya') return AQIDA_ATTRIBUTES.filter((a) => a.block === 'sanusi');
  return [];
}

